// CodeMon Creature Database & Stat Generator

const CODEMON_TYPES = {
  BUG: 'bug',
  CODE: 'code',
  MEMORY: 'memory',
  LOGIC: 'logic',
  FLOW: 'flow'
};

// Each type beats the next one round the loop and loses to the one before it:
// bug breaks code, code solves logic, logic organises memory, memory buffers
// flow, and flow routes around bugs. Normal moves are neutral against everything.
const TYPE_CYCLE = ['bug', 'code', 'logic', 'memory', 'flow'];
const SUPER_EFFECTIVE = 1.5;
const NOT_VERY_EFFECTIVE = 0.67;

/** Damage multiplier for a move of `moveType` hitting a creature of `defenderType`. */
function typeEffectiveness(moveType, defenderType) {
  const a = TYPE_CYCLE.indexOf(moveType);
  const d = TYPE_CYCLE.indexOf(defenderType);
  if (a < 0 || d < 0) return 1;
  if ((a + 1) % TYPE_CYCLE.length === d) return SUPER_EFFECTIVE;
  if ((d + 1) % TYPE_CYCLE.length === a) return NOT_VERY_EFFECTIVE;
  return 1;
}

