const MOVE_POOL = {
  'Scratch': { power: 12, accuracy: 100, type: 'normal', category: 'physical' },
  'StringConcat': { power: 15, accuracy: 90, type: 'code', category: 'special' },
  'Bite': { power: 18, accuracy: 85, type: 'bug', category: 'physical' },
  'Crash': { power: 28, accuracy: 75, type: 'code', category: 'special' },
  'StackOverflow': { power: 32, accuracy: 70, type: 'logic', category: 'special' },
  'DebugAttack': { power: 24, accuracy: 95, type: 'code', category: 'physical' },
  'CacheStore': { power: 20, accuracy: 100, type: 'memory', category: 'special' },
  'DataShift': { power: 18, accuracy: 95, type: 'memory', category: 'physical' },
  'LeakDetect': { power: 25, accuracy: 80, type: 'memory', category: 'special' },
  'IfStatement': { power: 16, accuracy: 100, type: 'logic', category: 'special' },
  'BooleanFlip': { power: 14, accuracy: 100, type: 'logic', category: 'special' },
  'LogicalAnd': { power: 22, accuracy: 90, type: 'logic', category: 'physical' },
  'AsyncWave': { power: 20, accuracy: 100, type: 'flow', category: 'special' },
  'CallbackStrike': { power: 26, accuracy: 85, type: 'flow', category: 'physical' },
  'PromiseChain': { power: 30, accuracy: 75, type: 'flow', category: 'special' },
  'Tackle': { power: 10, accuracy: 100, type: 'normal', category: 'physical' },
  'Recover': { power: 0, accuracy: 100, type: 'normal', category: 'status', isHealing: true },
  'Harden': { power: 0, accuracy: 100, type: 'normal', category: 'status', isDefensive: true }
};

// Evolution. The sprite pack has no evolution lines, so a CodeMon evolves into a
// different, stronger species of its own type. Each type's 200 species are
// sorted by total base stats and cut into weak, middle and strong thirds; the
// k-th weakest of each third form one chain: weak[k] -> middle[k] -> strong[k].
// That makes every step a real jump in power, not a swap with a near-twin.
const EVOLVE_LEVELS = [16, 32];   // weak -> middle, middle -> strong
const baseTotal = (sp) => sp.baseHp + sp.baseAtk + sp.baseDef + sp.baseSp + sp.baseSpd;

/** species id -> { into, level } for every species that evolves, and its stage. */
const EVOLUTIONS = new Map();
const EVOLUTION_STAGE = new Map();   // species id -> 0 (base), 1 or 2
for (const type of TYPE_CYCLE) {
  const ranked = CODEMON_SPECIES.filter(sp => sp.type === type)
    .sort((a, b) => baseTotal(a) - baseTotal(b) || a.id - b.id);
  const third = Math.floor(ranked.length / 3);
  for (let k = 0; k < third; k++) {
    const [weak, middle, strong] = [ranked[k], ranked[third + k], ranked[2 * third + k]];
    EVOLUTIONS.set(weak.id, { into: middle, level: EVOLVE_LEVELS[0] });
    EVOLUTIONS.set(middle.id, { into: strong, level: EVOLVE_LEVELS[1] });
    EVOLUTION_STAGE.set(weak.id, 0);
    EVOLUTION_STAGE.set(middle.id, 1);
    EVOLUTION_STAGE.set(strong.id, 2);
  }
}

/**
 * Evolve `codemon` as far as its level allows; a high-level catch can go
 * straight through two stages. Returns the species it started as if it
 * evolved, otherwise null.
 */
function evolveFully(codemon) {
  const from = codemon.species;
  for (let into; (into = evolutionFor(codemon.species, codemon.level)); ) codemon.evolveInto(into);
  return codemon.species === from ? null : from;
}

/** The species this one evolves into at `level` or below, or null. */
function evolutionFor(species, level) {
  const evo = EVOLUTIONS.get(species.id);
  return evo && level >= evo.level ? evo.into : null;
}

// Shiny CodeMon: a rare wild one in different colours, with a sparkle. It's
// only a look - same stats - but it stays shiny when caught and when it evolves.
const SHINY_CHANCE = 1 / 64;
const SHINY_FILTER = 'hue-rotate(150deg) saturate(1.5) brightness(1.1)';

/** Whether a new wild CodeMon is shiny, from a random number in [0, 1). */
function rollShiny(random) {
  return random < SHINY_CHANCE;
}

// Area guardians. Each area has one: beat it to open the next area. The
// guardian is the most evolved, strongest CodeMon among that area's wild ones,
// at a fixed level, and it's tougher than a wild CodeMon of the same level.
// Wild CodeMon come in at lower levels when their species is strong; guardians
// don't, so these levels are kept modest: in 60 simulated autoplay runs, 22/32/42
// meant winning areas 2 and 3 only 6-12 levels above the guardian.
const GUARDIAN_LEVELS = [12, 20, 28, 36];
const GUARDIAN_HP_BONUS = 1.25;    // times a wild CodeMon's HP at that level
const GUARDIAN_GOLD = 200;

/**
 * The guardian's species for an area whose wild CodeMon are ids lo..hi: the most
 * evolved stage found there (the first area has no final stages), and of those
 * the one with the highest base stats.
 */
function guardianSpecies(lo, hi) {
  const rank = (sp) => (EVOLUTION_STAGE.get(sp.id) || 0) * 10000 + baseTotal(sp);
  return CODEMON_SPECIES
    .filter(sp => sp.id >= lo && sp.id <= hi)
    .reduce((best, sp) => (!best || rank(sp) > rank(best) ? sp : best), null);
}

/**
 * `level`, scaled for how strong `species` is next to the starters: a species
 * with better base stats comes in a few levels lower, so a fight is close
 * rather than even-on-paper. Not rounded.
 */
function levelForStrength(level, species) {
  const starterTotal = [1, 2, 5]
    .map(id => baseTotal(CODEMON_SPECIES.find(sp => sp.id === id)))
    .reduce((a, b) => a + b) / 3;
  return level * Math.sqrt(starterTotal / baseTotal(species));
}

// Area trainers: an optional fight in each area against a computer trainer with
// three CodeMon, one after another, with no break to heal in between. Beating
// one pays gold; it doesn't open anything. TRAINER_LEVELS are per area, then
// scaled for each species' strength the way wild ones are, which brings every
// trainer CodeMon under its guardian's level. They were picked with
// scripts/sim-trainers.mjs (a lone evolved starter at the guardian's level - 2,
// no items) so that even the weakest starter usually has a chance. A lone
// starter there wins (Byteling/BitRiot/Flowy): 45/97/100%, 31/100/100%,
// 67/100/100% and 53/59/100%. Starter choice matters more than any one level:
// Byteling struggles in the middle two areas at every level that leaves the
// others a fight.
const TRAINER_NAMES = ['Intern Ivy', 'Sysadmin Sam', 'Hacker Hex', 'Architect Ada'];
const TRAINER_LEVELS = [6, 15, 23, 44];
const TRAINER_GOLD = 120;

/**
 * A trainer's team for an area whose wild CodeMon are ids lo..hi: three species
 * spread across the area (never its guardian), around `level` once scaled for
 * strength, the last a level up on the first. Always the same team, so the
 * trainer you lost to is the one you face again.
 */
function trainerTeam(lo, hi, level) {
  const guardian = guardianSpecies(lo, hi);
  const pool = CODEMON_SPECIES.filter(sp => sp.id >= lo && sp.id <= hi && sp !== guardian);
  return [0.25, 0.5, 0.75].map((f, i) => {
    const species = pool[Math.floor(f * (pool.length - 1))];
    return { species, level: Math.max(2, Math.round(levelForStrength(level + i - 1, species))) };
  });
}

/** Area 0 is always open; any other needs the previous area's guardian beaten. */
function isAreaOpen(beaten, areaIdx) {
  return areaIdx === 0 || beaten.includes(areaIdx - 1);
}

class Codemon {
  constructor(species, level = 1) {
    this.species = species;
    this.level = level;
    this.exp = 0;
    this.expToLevel = species.expToLevel;
    this.hp = this.getMaxHp();
    this.currentHp = this.hp;
    this.moves = [...species.moves];
    this.shiny = false;           // see rollShiny; kept through catching and evolving
    this.stats = {
      atk: this.getAtk(),
      def: this.getDef(),
      sp: this.getSp(),
      spd: this.getSpd()
    };
    this.id = Math.random().toString(36).substr(2, 9);
  }

  getMaxHp() {
    return Math.floor((2 * this.species.baseHp * this.level) / 100 + this.level + 5);
  }

  getAtk() {
    return Math.floor((2 * this.species.baseAtk * this.level) / 100 + 5);
  }

  getDef() {
    return Math.floor((2 * this.species.baseDef * this.level) / 100 + 5);
  }

  getSp() {
    return Math.floor((2 * this.species.baseSp * this.level) / 100 + 5);
  }

  getSpd() {
    return Math.floor((2 * this.species.baseSpd * this.level) / 100 + 5);
  }

  /**
   * Turn into `species`, keeping level and progress. Stats and moves come from
   * the new species; HP keeps the same fraction of the (higher) new maximum, so
   * evolving mid-adventure doesn't hand out a free heal.
   */
  evolveInto(species) {
    const hpFraction = this.hp > 0 ? this.currentHp / this.hp : 1;
    this.species = species;
    // Never below the new species' starting threshold: loadGame raises anything
    // lower to it, so the same CodeMon used to level slower after a reload.
    this.expToLevel = Math.max(this.expToLevel, species.expToLevel);
    this.hp = this.getMaxHp();
    this.currentHp = Math.max(this.currentHp > 0 ? 1 : 0, Math.round(this.hp * hpFraction));
    this.stats = { atk: this.getAtk(), def: this.getDef(), sp: this.getSp(), spd: this.getSpd() };
    this.moves = [...species.moves];
  }

  learnMove(moveName) {
    if (this.moves.length < 4 && !this.moves.includes(moveName)) {
      this.moves.push(moveName);
    }
  }

  gainExp(amount) {
    this.exp += amount;
    while (this.exp >= this.expToLevel) {
      this.levelUp();
    }
  }

  levelUp() {
    this.exp -= this.expToLevel;
    this.level++;
    this.expToLevel = Math.floor(this.expToLevel * 1.1);
    this.hp = this.getMaxHp();
    this.currentHp = this.hp;
    this.stats.atk = this.getAtk();
    this.stats.def = this.getDef();
    this.stats.sp = this.getSp();
    this.stats.spd = this.getSpd();
  }

  takeDamage(damage) {
    this.currentHp = Math.max(0, this.currentHp - damage);
  }

  heal(amount) {
    this.currentHp = Math.min(this.hp, this.currentHp + amount);
  }

  getMove(moveName) {
    return MOVE_POOL[moveName];
  }
}

// Shop prices in gold. A win pays 50 and a catch 30, so a potion costs half a
// win, a Pokéball a bit under one, and a Great Ball two.
const SHOP_PRICES = {
  pokeball: 40,
  greatball: 100,
  potion: 25,
};

/**
 * What autoplay should buy next between fights, or null. Potions first, since
 * running out of those is what ends a run; then Pokéballs. Only tops each up to 2,
 * and only when it can pay.
 */
function nextRestock(player) {
  return ['potion', 'pokeball'].find(k => (player.items[k] || 0) < 2
                                       && player.gold >= SHOP_PRICES[k]) || null;
}

// A team holds 6. Catches beyond that go to the storage box, which holds this many.
const TEAM_SIZE = 6;
const BOX_SIZE = 30;

class Player {
  constructor() {
    this.level = 1;
    this.exp = 0;
    this.gold = 100;
    this.team = [];
    this.box = [];
    this.pokedex = new Set();
    this.items = {
      pokeball: 5,
      greatball: 2,
      potion: 3,
      antidote: 1
    };
  }

  /** Where a catch goes: 'team', 'box' once the team is full, or false if both are full. */
  addCodemon(codemon) {
    const into = this.team.length < TEAM_SIZE ? 'team' : this.box.length < BOX_SIZE ? 'box' : false;
    if (!into) return false;
    this[into].push(codemon);
    this.pokedex.add(codemon.species.id);
    return into;
  }

  /** Whether a catch has somewhere to go. */
  hasRoom() {
    return this.team.length < TEAM_SIZE || this.box.length < BOX_SIZE;
  }

  /** Move a stored CodeMon onto the team, if it has a free slot. */
  withdrawFromBox(boxIdx) {
    if (!Number.isInteger(boxIdx) || !this.box[boxIdx] || this.team.length >= TEAM_SIZE) return false;
    this.team.push(...this.box.splice(boxIdx, 1));
    this.leadWithAFighter();
    return true;
  }

  /** Store a team member. The team keeps at least one CodeMon that can fight. */
  depositToBox(teamIdx) {
    if (!Number.isInteger(teamIdx) || !this.team[teamIdx] || this.box.length >= BOX_SIZE) return false;
    if (!this.team.some((c, i) => i !== teamIdx && c.currentHp > 0)) return false;
    this.box.push(...this.team.splice(teamIdx, 1));
    this.leadWithAFighter();
    return true;
  }

  /** Trade a team member for a stored one, in the same team slot. */
  swapWithBox(teamIdx, boxIdx) {
    if (!Number.isInteger(teamIdx) || !Number.isInteger(boxIdx)) return false;
    const out = this.team[teamIdx], into = this.box[boxIdx];
    if (!out || !into) return false;
    if (into.currentHp <= 0 && !this.team.some((c, i) => i !== teamIdx && c.currentHp > 0)) return false;
    this.team[teamIdx] = into;
    this.box[boxIdx] = out;
    this.leadWithAFighter();
    return true;
  }

  /** Battles send out team[0], so keep a CodeMon that can fight in front. */
  leadWithAFighter() {
    const first = this.team.findIndex(c => c.currentHp > 0);
    if (first > 0) this.team.unshift(...this.team.splice(first, 1));
  }

  getActiveCodemon() {
    return this.team.length > 0 ? this.team[0] : null;
  }

  switchCodemon(index) {
    if (index >= 0 && index < this.team.length && this.team[index].currentHp > 0) {
      [this.team[0], this.team[index]] = [this.team[index], this.team[0]];
      return true;
    }
    return false;
  }

  usePotion() {
    if (this.items.potion > 0) {
      const active = this.getActiveCodemon();
      if (active && active.currentHp < active.hp) {
        active.heal(20);
        this.items.potion--;
        return true;
      }
    }
    return false;
  }

  useItem(itemType) {
    if (this.items[itemType] > 0) {
      this.items[itemType]--;
      return true;
    }
    return false;
  }

  /**
   * Buy `qty` of an item from the shop. Returns false, and changes nothing, for
   * an item the shop doesn't sell, a quantity that isn't a positive whole number,
   * or not enough gold.
   */
  buy(itemType, qty = 1) {
    // hasOwn, not a plain lookup: SHOP_PRICES['constructor'] is a function, and
    // buying it turned gold into NaN.
    if (!Object.hasOwn(SHOP_PRICES, itemType)) return false;
    const price = SHOP_PRICES[itemType];
    if (!Number.isInteger(qty) || qty < 1) return false;
    const cost = price * qty;
    if (this.gold < cost) return false;
    this.gold -= cost;
    this.items[itemType] = (this.items[itemType] || 0) + qty;
    return true;
  }

  addGold(amount) {
    this.gold += amount;
  }

  addExp(amount) {
    this.exp += amount;
  }
}

window.Codemon = Codemon;
window.Player = Player;
window.TEAM_SIZE = TEAM_SIZE;
window.BOX_SIZE = BOX_SIZE;
window.CODEMON_SPECIES = CODEMON_SPECIES;
window.MOVE_POOL = MOVE_POOL;
window.SHOP_PRICES = SHOP_PRICES;
window.nextRestock = nextRestock;
window.evolutionFor = evolutionFor;
window.evolveFully = evolveFully;
window.guardianSpecies = guardianSpecies;
window.trainerTeam = trainerTeam;
window.levelForStrength = levelForStrength;
window.rollShiny = rollShiny;
window.SHINY_FILTER = SHINY_FILTER;
window.isAreaOpen = isAreaOpen;
window.EVOLUTION_STAGE = EVOLUTION_STAGE;
